  protected readonly dueTotal = computed(() => {
    const crew = this.crew();
    return money(crewIds(crew).reduce((t, id) => t + (this.dues().get(id) ?? 0), 0));
  });

  protected readonly personId = new FormControl('', { nonNullable: true });
